parts.text:
{
  "units": [
    {
      "quote": "The goal is the best likeness that can reasonably be obtained:",
      "scope_quotes": ["d. Infants pose a particular challenge."],
      "kind": "statement",
      "meaning": "When dealing with photographs of infants, the overarching objective is to obtain the best likeness of the child that can reasonably be achieved given the particular challenge infants pose."
    },
    {
      "quote": "It is acceptable if the infant's eyes, particularly a newborn's, are partially or completely closed;",
      "scope_quotes": [
        "d. Infants pose a particular challenge.",
        "The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "In photographs of infants (particularly newborns), it is permissible for the child's eyes to be partially or completely closed."
    },
    {
      "quote": "The infant's head may be discreetly supported, e.g., a car seat with a white or off-white blanket behind the child.",
      "scope_quotes": [
        "d. Infants pose a particular challenge.",
        "The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "An infant's head is permitted to be supported discreetly in the photograph, such as by placing the infant in a car seat with a white or off-white blanket behind the child."
    },
    {
      "quote": "Head tilt is acceptable for infants; and",
      "scope_quotes": [
        "d. Infants pose a particular challenge.",
        "The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "It is permissible for an infant's head to be tilted in the photograph."
    },
    {
      "quote": "A parent’s face cannot be in the photograph of the infant.",
      "scope_quotes": ["d. Infants pose a particular challenge."],
      "kind": "prohibition",
      "meaning": "A parent's face is strictly prohibited from appearing in the photograph of an infant."
    },
    {
      "quote": "You must request a new photograph if the photograph submitted does not meet the following requirements:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "An adjudicator or examiner is required to request a new photograph from the applicant whenever the submitted photograph fails to satisfy the specified requirements."
    },
    {
      "quote": "The photograph must be in color;",
      "scope_quotes": ["You must request a new photograph if the photograph submitted does not meet the following requirements:"],
      "kind": "requirement",
      "meaning": "Submitted photographs are required to be in color, and a new photograph must be requested if this requirement is not met."
    },
    {
      "quote": "The photograph should be taken within six months of submitting the application, be a good likeness of and satisfactorily identify the applicant at the time of the application (see 22 CFR 51.26).",
      "scope_quotes": ["You must request a new photograph if the photograph submitted does not meet the following requirements:"],
      "kind": "recommendation",
      "meaning": "The submitted photograph should be taken within six months prior to application submission, must represent a good likeness, and must satisfactorily identify the applicant at the time of application under 22 CFR 51.26."
    },
    {
      "quote": "A photograph showing a change in hairstyle or facial hair from the identification document submitted is acceptable if it still is a good likeness of the applicant;",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph should be taken within six months of submitting the application, be a good likeness of and satisfactorily identify the applicant at the time of the application (see 22 CFR 51.26)."
      ],
      "kind": "permission",
      "meaning": "A photograph that reflects a different hairstyle or facial hair compared to the applicant's submitted identification document is acceptable provided that it remains a good likeness of the applicant."
    },
    {
      "quote": "Applicants may wish to re-use a passport photograph that is depicted on their submitted U.S Certificate of Citizenship or Certificate of Naturalization.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Applicants sometimes seek to reuse a passport photograph that appears on their submitted U.S. Certificate of Citizenship or Certificate of Naturalization."
    },
    {
      "quote": "Be aware that even if the certificate itself was recently issued, because of U.S. Citizenship and Immigration Services processing times, the photograph may not have been taken within six months of submitting the application.",
      "scope_quotes": ["NOTE: Applicants may wish to re-use a passport photograph that is depicted on their submitted U.S Certificate of Citizenship or Certificate of Naturalization."],
      "kind": "statement",
      "meaning": "Examiners are cautioned that even if a Certificate of Citizenship or Naturalization was recently issued, U.S. Citizenship and Immigration Services processing timelines mean the photograph on it might not have been taken within the required six months prior to submitting the passport application."
    },
    {
      "quote": "The photograph must be free of material damage:",
      "scope_quotes": ["You must request a new photograph if the photograph submitted does not meet the following requirements:"],
      "kind": "requirement",
      "meaning": "The submitted photograph must be completely free of material damage; failure to satisfy this requirement requires requesting a new photograph."
    },
    {
      "quote": "Material damage is any damage to the facial area that makes the photograph no longer a good likeness of the applicant (e.g., creases, large holes, and large smudges) or impedes the functioning of facial recognition (damage in the area of the eyes);",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Material damage is defined as any facial area damage that prevents the photograph from being a good likeness of the applicant (such as creases, large holes, or large smudges) or any damage in the eye region that interferes with facial recognition functioning."
    },
    {
      "quote": "Immaterial damage is any damage to the background, and non-material damage to the facial area (e.g., staple holes).",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Immaterial damage is defined as any damage restricted to the background of the photograph as well as non-material damage to the facial area, including staple holes."
    },
    {
      "quote": "Immaterial damage is acceptable;",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:",
        "(b) Immaterial damage is any damage to the background, and non-material damage to the facial area (e.g., staple holes)."
      ],
      "kind": "permission",
      "meaning": "Photographs that exhibit only immaterial damage (such as background damage or staple holes in the facial area) are permitted and acceptable."
    },
    {
      "quote": "The applicant does not need to sign the photograph, as this often causes creases or smudges; and",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "exemption",
      "meaning": "Applicants are not required or expected to sign their photograph, as signing often produces creases or smudges."
    },
    {
      "quote": "For hand-carry applications, the acceptance agent signs the back of the photograph.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "requirement",
      "meaning": "When processing hand-carry applications, the acceptance agent is required to sign the back of the photograph."
    },
    {
      "quote": "A photograph that appears acceptable and undamaged in the system may have a defect that is apparent when the passport is printed.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "statement",
      "meaning": "A photograph showing no apparent damage or issues in the electronic system may still contain defects that only become visible once the passport is printed."
    },
    {
      "quote": "Consequently, the passport application may be returned to adjudication to request a new photograph even though the photograph appeared acceptable.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "(6) The photograph must be free of material damage:",
        "(d) A photograph that appears acceptable and undamaged in the system may have a defect that is apparent when the passport is printed."
      ],
      "kind": "permission",
      "meaning": "A passport application is permitted to be sent back to adjudication to obtain a new photograph if a printing defect arises, notwithstanding that the photo initially appeared acceptable in the system."
    },
    {
      "quote": "Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes.",
      "scope_quotes": ["e. Eyeglasses/contact lenses:"],
      "kind": "prohibition",
      "meaning": "Wearing eyeglasses in passport photographs is prohibited, except in cases where they cannot be removed for medical reasons, such as recent ocular surgery necessitating eye protection."
    },
    {
      "quote": "A medical statement signed by a medical professional/health practitioner must be requested in these rare circumstances.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "(1) Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes."
      ],
      "kind": "requirement",
      "meaning": "In the rare circumstances where an applicant cannot remove eyeglasses for medical reasons, staff must request a signed medical statement from a medical professional or health practitioner."
    },
    {
      "quote": "The frames of the eyeglasses must not cover the eye(s);",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted under a medical exception, the frames are strictly prohibited from covering any part of the applicant's eye or eyes."
    },
    {
      "quote": "There must not be glare on eyeglasses that obscures the eye(s);",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted for medical reasons, there must be no glare on the lenses that obscures the applicant's eye or eyes."
    },
    {
      "quote": "There must not be shadows or refraction from the eyeglasses that obscure the eye(s); and",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted for medical reasons, neither shadows nor refraction caused by the eyeglasses may obscure the applicant's eye or eyes."
    },
    {
      "quote": "Dark or tinted lenses are permitted if the medical statement also indicates that they are required.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "permission",
      "meaning": "When eyeglasses are accepted for medical reasons, dark or tinted lenses are permitted only on the condition that the signed medical statement explicitly indicates that dark or tinted lenses are required."
    }
  ]
}
